package com.android.purebilibili.feature.video.playback.loader

import com.android.purebilibili.feature.video.usecase.VideoLoadResult
import com.bilipai.desktop.ui.DesktopOriginalVideoLoadPort as VideoPlaybackUseCase

internal data class PlaybackLoadConfig(
    val defaultQuality: Int,
    val audioQualityPreference: Int,
    val videoCodecPreference: String,
    val videoSecondCodecPreference: String,
    val playWhenReady: Boolean,
    val isAv1Supported: Boolean,
    val isHdrSupported: Boolean,
    val isDolbyVisionSupported: Boolean
)

internal class PlaybackLoader(
    private val loadVideo: suspend (PlaybackRequest, PlaybackLoadConfig) -> VideoLoadResult
) {

    suspend fun load(
        request: PlaybackRequest,
        cachedPositionMs: Long,
        config: PlaybackLoadConfig
    ): PlaybackLoadResult {
        val result = loadVideo(request, config)
        return PlaybackLoadResult.from(
            request = request,
            cachedPositionMs = cachedPositionMs,
            result = result
        )
    }

    companion object {
        fun from(useCase: VideoPlaybackUseCase): PlaybackLoader {
            return PlaybackLoader { request, config ->
                useCase.loadVideo(
                    bvid = request.bvid,
                    aid = request.aid,
                    cid = request.cid,
                    defaultQuality = config.defaultQuality,
                    audioQualityPreference = config.audioQualityPreference,
                    videoCodecPreference = config.videoCodecPreference,
                    videoSecondCodecPreference = config.videoSecondCodecPreference,
                    audioLang = request.audioLang,
                    playWhenReady = config.playWhenReady,
                    isAv1SupportedOverride = config.isAv1Supported,
                    isHdrSupportedOverride = config.isHdrSupported,
                    isDolbyVisionSupportedOverride = config.isDolbyVisionSupported
                )
            }
        }
    }
}

//  [性能优化] 并行请求视频详情、相关推荐。
// 表情映射在首帧链路中跳过，避免自动播放起播被非关键请求阻塞。
val (detailResult, relatedVideos, emoteMap) = kotlinx.coroutines.coroutineScope {
    val bootstrapMode = resolvePlaybackBootstrapMode(
        bvid = bvid,
        cid = cid
    )
    // 起播关键路径只等待 playinfo/播放地址，不等待相关推荐。
    // 相关推荐由 ViewModel 在播放器 prepare 后异步拉取。
    val emoteMap = if (com.android.purebilibili.data.repository.shouldFetchCommentEmoteMapOnVideoLoad()) {
        environment.emoteMap()
    } else {
        emptyMap()
    }

    val mergedDetailResult = when (bootstrapMode) {
        PlaybackBootstrapMode.DETAIL_AND_PLAYURL_PARALLEL -> {
            val infoDeferred = async {
                VideoRepository.getVideoInfoOnly(
                    bvid = bvid,
                    aid = aid,
                    requestedCid = cid
                )
            }
            val playUrlDeferred = async {
                VideoRepository.getInitialPlayUrlData(
                    bvid = bvid,
                    cid = cid,
                    targetQuality = defaultQuality,
                    audioLang = audioLang
                )
            }

            infoDeferred.await().fold(
                onSuccess = { info ->
                    val playData = playUrlDeferred.await()
                    if (playData == null) {
                        Result.failure(Exception("无法获取播放地址"))
                    } else {
                        Result.success(info to playData)
                    }
                },
                onFailure = { error ->
                    Result.failure(error)
                }
            )
        }

        PlaybackBootstrapMode.DETAIL_ONLY -> {
            VideoRepository.getVideoDetails(
                bvid = bvid,
                aid = aid,
                requestedCid = cid,
                targetQuality = defaultQuality,
                audioLang = audioLang
            )
        }
    }

    val relatedVideos = emptyList<RelatedVideo>()

    Triple(mergedDetailResult, relatedVideos, emoteMap)
}

