private fun publishVideoDetailInfo(info: ViewInfo, requestBvid: String, requestToken: Long) {
    environment.assertCurrent()
    if (currentLoadRequestToken != requestToken || currentBvid != requestBvid) return
    _detailState.update { state ->
        if (state.requestToken == requestToken) {
            state.copy(
                info = info,
                isLoggedIn = VideoRepository.isPlaybackLoggedIn(),
                isVip = VideoRepository.isPlaybackVip()
            )
        } else state
    }
    // Detail-only data cannot publish subject/action/native success. Related
    // loading keeps the existing real accepted-publication chain in this slice.
}

